import { Link } from '@tanstack/react-router';
import { useProjects } from './projects';

// The projects list. Reads server data straight from its query key and shows the client's NAME
// (served alongside each project), not the id.
export function ProjectList() {
  const { data: projects } = useProjects();

  if (!projects) {
    return null;
  }

  if (projects.length === 0) {
    return <p data-testid="projects-empty">No projects yet.</p>;
  }

  return (
    <table data-testid="projects-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Client</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {projects.map((project) => (
          <tr key={project.id} data-testid={`project-row-${project.id}`}>
            <td data-testid="project-name">{project.name}</td>
            <td data-testid="project-client">{project.clientName}</td>
            <td>
              <Link
                to="/projects/$projectId"
                params={{ projectId: String(project.id) }}
                data-testid={`project-open-${project.id}`}
              >
                Open
              </Link>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// The shape the server returns (a project joined to its client's name) and the query key everything
// that shows projects shares. Invalidating ['projects'] refreshes every view of projects.
export type Project = { id: number; name: string; clientId: number; clientName: string };

export const projectsKey = ['projects'] as const;

export function useProjects() {
  return useQuery({
    queryKey: projectsKey,
    queryFn: () => getJson<Project[]>('/api/projects'),
  });
}

export function useCreateProject() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { name: string; clientId: number }) =>
      postJson<Project>('/api/projects', input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: projectsKey }),
  });
}

// The client choices the project form needs. Reads the SHARED ['clients'] key — no import of the
// clients feature; the two stay in step through the key, not a dependency.
type ClientOption = { id: number; name: string };

export function useClientOptions() {
  return useQuery({
    queryKey: ['clients'] as const,
    queryFn: () => getJson<ClientOption[]>('/api/clients'),
  });
}
import { InvoiceLineItemRow } from '../../slots/defs/invoiceLineItemRow';
import type { LineItem } from './lineItems';
import { useRemoveLineItem } from './lineItems';

// "Take this line off the invoice" — a self-contained row action filling the line-item row region.
// The table is not edited to add it (CLAUDE.md rule 3); it fills the slot the table renders per row.
// Clicking removes the line through the shared mutation, which invalidates ['lineItems', invoiceId]
// so the list and its worked-out total re-read from the server — the total drops with no hand-count.
function RemoveLineItem({ lineItem }: { lineItem: LineItem }) {
  const remove = useRemoveLineItem(lineItem.invoiceId);
  return (
    <button
      type="button"
      data-testid={`lineitem-remove-${lineItem.id}`}
      disabled={remove.isPending}
      onClick={() => remove.mutate(lineItem.id)}
    >
      Remove
    </button>
  );
}

export const contribution = InvoiceLineItemRow.fill({ order: 10, Component: RemoveLineItem });
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// A line item on an invoice: one thing being charged for — a description, how many (qty) and the
// price of each (unitPrice). Everything that shows an invoice's lines shares the key
// ['lineItems', invoiceId]; invalidating it after a write refreshes the list and its total together.
export type LineItem = {
  id: number;
  invoiceId: number;
  description: string;
  qty: number;
  unitPrice: number;
};

export const lineItemsKey = (invoiceId: number) => ['lineItems', invoiceId] as const;

export function useLineItems(invoiceId: number) {
  return useQuery({
    queryKey: lineItemsKey(invoiceId),
    queryFn: () => getJson<LineItem[]>(`/api/lineitems?invoiceId=${invoiceId}`),
  });
}

// Add a line to an invoice: POSTs {invoiceId, description, qty, unitPrice} and returns the saved row.
// Invalidates ['lineItems', invoiceId] so the line list and its total re-read from the server, and
// the ['invoices'] prefix so every invoice list (which shows the worked-out amount) refreshes too —
// the two stay in step by sharing the key, with no import between them.
export function useAddLineItem(invoiceId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { description: string; qty: number; unitPrice: number }) =>
      postJson<LineItem>('/api/lineitems', { invoiceId, ...input }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: lineItemsKey(invoiceId) });
      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
    },
  });
}

// Take a line off an invoice: POSTs {id} and returns the updated invoice. Invalidates the same keys
// as adding — ['lineItems', invoiceId] so the line list and its worked-out total re-read, and the
// ['invoices'] prefix so every invoice list showing the amount refreshes too. The total is never
// edited here; it drops because the list re-reads from the server (CLAUDE.md rule 5).
export function useRemoveLineItem(invoiceId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: number) => postJson<unknown>('/api/lineitems/remove', { id }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: lineItemsKey(invoiceId) });
      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
    },
  });
}

