package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.web.bind.annotation.RequestBody;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.ObjectResponse;

/**
 * {@code POST /api/lineitems/remove} — take a charge line off an invoice from an {id} body and return
 * the updated invoice. Wired by {@code officefloor/rest/api/lineitems/remove.POST.yml}. The line must
 * exist (404 otherwise). Removing a line re-works the invoice's amount (the sum of qty * unitPrice
 * across the lines that remain, zero when none are left) and stores it, so the total the UI shows is
 * always worked out from the lines, never typed — the mirror of {@link LineItemsPostLogic}.
 */
public class LineItemsRemoveLogic {

    public void service(@RequestBody RemoveLineItem body, LineItemRepository lineItems,
            InvoiceRepository invoices, ObjectResponse<Invoice> response) {
        Long id = body.getId();
        if (id == null) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "A line item id is required");
        }
        LineItem line = lineItems.findById(id)
                .orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND, "No such line item"));
        Long invoiceId = line.getInvoiceId();
        lineItems.delete(line);

        // Re-work the invoice's amount from the lines that remain and store it, so the figure stays
        // derived — the sum drops by exactly the removed line's amount.
        Invoice invoice = invoices.findById(invoiceId)
                .orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND, "No such invoice"));
        List<LineItem> lines = lineItems.findByInvoiceIdOrderByIdAsc(invoiceId);
        BigDecimal total = lines.stream().map(LineItem::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        invoice.setAmount(total);
        Invoice saved = invoices.save(invoice);

        response.send(saved);
    }

    /** Request body for removing a line item from an invoice. */
    public static class RemoveLineItem {
        private Long id;

        public Long getId() {
            return id;
        }

        public void setId(Long id) {
            this.id = id;
        }
    }
}
package net.officefloor.hq.app;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/projects} — list every project with the NAME of the client it is for (not just the
 * id), so the UI can show the join directly. Wired by {@code officefloor/rest/api/projects.GET.yml}.
 */
public class ProjectsGetLogic {

    public void service(ProjectRepository projects, ClientRepository clients,
            ObjectResponse<List<ProjectView>> response) {
        Map<Long, String> nameByClient = clients.findAll().stream()
                .collect(Collectors.toMap(Client::getId, Client::getName));
        List<ProjectView> views = projects.findAll().stream()
                .map(p -> new ProjectView(p.getId(), p.getName(), p.getClientId(),
                        nameByClient.get(p.getClientId())))
                .collect(Collectors.toList());
        response.send(views);
    }

    /** A project plus its client's name, as the projects list needs it. */
    public static class ProjectView {
        private final Long id;
        private final String name;
        private final Long clientId;
        private final String clientName;

        public ProjectView(Long id, String name, Long clientId, String clientName) {
            this.id = id;
            this.name = name;
            this.clientId = clientId;
            this.clientName = clientName;
        }

        public Long getId() {
            return id;
        }

        public String getName() {
            return name;
        }

        public Long getClientId() {
            return clientId;
        }

        public String getClientName() {
            return clientName;
        }
    }
}
package net.officefloor.hq.app;

import org.springframework.web.bind.annotation.RequestBody;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.ObjectResponse;

/**
 * {@code POST /api/projects} — create a project from a {name, clientId} body and return the saved row
 * (with its generated id). Wired by {@code officefloor/rest/api/projects.POST.yml}. A project must
 * belong to an existing client: the clientId is validated here and rejected with 400 before it
 * reaches the repository (the DB foreign key in Flyway V3 is the matching last line of defence).
 */
public class ProjectsPostLogic {

    public void service(@RequestBody NewProject newProject, ProjectRepository projects,
            ClientRepository clients, ObjectResponse<Project> response) {
        String name = newProject.getName();
        Long clientId = newProject.getClientId();
        if (name == null || name.trim().isEmpty()) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "A project name is required");
        }
        if (clientId == null || !clients.existsById(clientId)) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "A valid client is required");
        }
        Project saved = projects.save(new Project(name.trim(), clientId));
        response.send(saved);
    }

    /** Request body for creating a project. */
    public static class NewProject {
        private String name;
        private Long clientId;

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }

        public Long getClientId() {
            return clientId;
        }

        public void setClientId(Long clientId) {
            this.clientId = clientId;
        }
    }
}

